keyframes:
@keyframes ripple { 
  0% { opacity: 0; background-size: 0px 0px; transform: scale(0.1); mask-image: radial-gradient(circle, black 0%, black 0%, transparent 2%, transparent 100%); }
  10% { opacity: 1; background-size: 16px 16px; transform: scale(0.2); mask-image: radial-gradient(circle, black 0%, black 8%, transparent 12%, transparent 100%); }
  20% { transform: scale(0.3); mask-image: radial-gradient(circle, black 0%, black 18%, transparent 22%, transparent 100%); }
  30% { transform: scale(0.4); mask-image: radial-gradient(circle, black 0%, black 28%, transparent 32%, transparent 100%); }
  40% { transform: scale(0.5); mask-image: radial-gradient(circle, transparent 0%, black 38%, transparent 42%, transparent 100%); }
  50% { transform: scale(0.6); mask-image: radial-gradient(circle, transparent 0%, black 48%, transparent 52%, transparent 100%); }
  60% { transform: scale(0.7); mask-image: radial-gradient(circle, transparent 0%, black 58%, transparent 62%, transparent 100%); }
  70% { transform: scale(0.8); mask-image: radial-gradient(circle, transparent 0%, black 68%, transparent 72%, transparent 100%); }
  80% { transform: scale(0.9); mask-image: radial-gradient(circle, transparent 0%, black 78%, transparent 82%, transparent 100%); }
  90% { transform: scale(0.95); mask-image: radial-gradient(circle, transparent 0%, black 88%, transparent 92%, transparent 100%); }
  100% { opacity: 0; background-size: 0px 0px; transform: scale(1); mask-image: radial-gradient(circle, transparent 0%, transparent 100%); }
}

